import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";

export default function App() {
  const [dark, setDark] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [active, setActive] = useState("home");

  // Scroll Spy
  useEffect(() => {
    const handler = () => {
      const sections = ["home", "about", "vision", "projects", "skills", "timeline", "papers", "news", "blog"];
      let current = "home";
      sections.forEach((id) => {
        const sec = document.getElementById(id);
        if (sec && window.scrollY >= sec.offsetTop - 120) current = id;
      });
      setActive(current);
    };
    window.addEventListener("scroll", handler);
    return () => window.removeEventListener("scroll", handler);
  }, []);

  const toggleTheme = () => setDark((d) => !d);

  return (
    <div className={dark ? "dark" : ""}>
      <div className="min-h-screen transition-colors duration-500 bg-neutral-950 text-neutral-100 dark:text-neutral-100">

        {/* Futuristic Scientific Background */}
        <div className="fixed inset-0 -z-10 select-none pointer-events-none">
          <div className="absolute w-[70vw] h-[70vh] bg-cyan-400/10 blur-[120px] rounded-full -top-32 -left-24" />
          <div className="absolute w-[50vw] h-[50vh] bg-fuchsia-400/10 blur-[120px] rounded-full bottom-0 right-0" />
        </div>

        {/* NAVBAR */}
        <header className="sticky top-0 z-50 backdrop-blur-xl bg-neutral-900/50 border-b border-neutral-800">
          <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
            <a href="#home" className="font-semibold tracking-tight text-xl">Khalil Braham</a>
            <nav className="hidden md:flex items-center gap-6 text-sm">
              {["home","about","vision","projects","skills","timeline","papers","news","blog"].map((id) => (
                <a key={id} href={`#${id}`} className={active===id ? "text-cyan-400" : "hover:text-cyan-300"}>{id.toUpperCase()}</a>
              ))}
            </nav>
            <div className="flex gap-2">
              <button onClick={() => setMenuOpen(!menuOpen)} className="md:hidden px-3 py-1 rounded bg-neutral-800">☰</button>
              <button onClick={toggleTheme} className="px-3 py-1 rounded bg-neutral-200 text-neutral-800">{dark ? "Light" : "Dark"}</button>
            </div>
          </div>

          {menuOpen && (
            <div className="md:hidden flex flex-col bg-neutral-900/80 px-6 py-4 text-sm gap-3">
              {["home","about","vision","projects","skills","timeline","papers","news","blog"].map((id) => (
                <a key={id} href={`#${id}`} onClick={()=>setMenuOpen(false)} className={active===id ? "text-cyan-400" : "hover:text-cyan-300"}>{id.toUpperCase()}</a>
              ))}
            </div>
          )}
        </header>

        {/* HERO */}
        <section id="home" className="max-w-6xl mx-auto text-center pt-32 pb-20 px-6">
          <motion.h1 initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:0.6}} className="text-5xl font-bold">
            Generative AI & LLMs for Scientific Intelligence
          </motion.h1>
          <p className="mt-4 opacity-80 text-lg">Diffusion • Flow Matching • Alignment • Drug Discovery</p>
        </section>

        {/* ABOUT */}
        <section id="about" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">About</h2>
          <p className="mt-4 leading-relaxed opacity-90">Researching generative modeling and large language models across discrete scientific domains (molecules, biological systems, code). Collaborating with Sanofi on pharmacology LLM alignment.</p>
        </section>

        {/* PROJECT CARDS */}
        <section id="projects" className="max-w-6xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">Research Projects</h2>
          <div className="grid md:grid-cols-3 gap-6 mt-6">
            {["Flow-Matching for Molecules","LLM Agents for Science","Graph Diffusion for Drug Candidates"].map((p)=> (
              <motion.div key={p} whileHover={{scale:1.03}} className="p-5 bg-neutral-900/40 border border-neutral-800 rounded-xl">
                <h3 className="font-semibold text-lg mb-2">{p}</h3>
                <p className="opacity-70 text-sm">Autonomous discovery pipelines, multimodal symbolic reasoning, and robust molecule generation.</p>
              </motion.div>
            ))}
          </div>
        </section>

        {/* SKILLS CLOUD */}
        <section id="skills" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">Skills</h2>
          <div className="flex flex-wrap gap-2 mt-6">
            {["PyTorch","RAG","Diffusion Models","Flow Matching","RLHF","Molecular Modeling","Graph ML","Attention","Optimization","CUDA","Linux","MLOps"].map((s)=> (
              <span key={s} className="px-3 py-1 rounded-full bg-cyan-500/20 border border-cyan-400/30 text-sm">{s}</span>
            ))}
          </div>
        </section>

        {/* TIMELINE */}
        <section id="timeline" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">Experience & Milestones</h2>
          <div className="border-l border-neutral-700 ml-4 mt-6 space-y-6">
            {[
              ["2025–","Polytechnique & Inria — Discrete generative modeling"],
              ["2024–2025","Sanofi — LLM pharmacology alignment"],
              ["2023–2024","Retail analytics — Time-series shape modeling"],
            ].map(([date,desc]) => (
              <div key={date} className="pl-6 relative">
                <div className="w-3 h-3 bg-cyan-400 rounded-full absolute -left-[7px] top-1.5" />
                <p className="text-sm opacity-70">{date}</p>
                <p className="text-base">{desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* PUBLICATIONS */}
        <section id="papers" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">Selected Publications</h2>
          <p className="mt-4 opacity-60">BibTeX ingestion coming.</p>
        </section>

        {/* NEWS */}
        <section id="news" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">News</h2>
          <ul className="mt-4 opacity-80 list-disc pl-6">
            <li>2025 — Starting collaboration with Sanofi.</li>
            <li>2025 — Experiments with flow-matching on molecular graphs.</li>
          </ul>
        </section>

        {/* BLOG */}
        <section id="blog" className="max-w-5xl mx-auto py-20 px-6">
          <h2 className="text-3xl font-semibold">Blog Notes</h2>
          <ul className="mt-4 opacity-80 list-disc pl-6">
            <li>Agentic reasoning for science.</li>
            <li>Symbolic constraints in molecular diffusion.</li>
          </ul>
        </section>

        {/* FOOTER */}
        <footer className="py-12 text-center opacity-50 text-sm">© {new Date().getFullYear()} — Khalil Braham</footer>
      </div>
    </div>
  );
}
